import React, { useState, useEffect } from "react";
import "bootstrap/dist/css/bootstrap.min.css";
import { useParams } from "react-router-dom";
import private_api from "../../server/private_api";

const LecionaAvaliacao = () => {
  const { id } = useParams(); // ID do professor
  const [cursos, setCursos] = useState([]);
  const [avaliacoes, setAvaliacoes] = useState([]);
  const [carregando, setCarregando] = useState(true);

  const formatarDataParaInput = (date) => {
    const d = new Date(date);
    d.setMinutes(d.getMinutes() - d.getTimezoneOffset());
    return d.toISOString().slice(0, 16);
  };

  const calcularDataFimPadrao = (dataInicio) => {
    const data = new Date(dataInicio);
    data.setHours(data.getHours() + 1);
    return formatarDataParaInput(data);
  };

  const [novaAvaliacao, setNovaAvaliacao] = useState({
    titulo: "",
    descricao: "",
    dataInicio: formatarDataParaInput(new Date()),
    dataFim: calcularDataFimPadrao(new Date()),
    pontuacaoMaxima: 20,
    cursoId: "",
    tipo: "escolha_multipla",
    perguntas: [
      {
        texto: "",
        opcoes: ["", "", "", ""],
        respostaCorreta: 0,
      },
    ],
    professorId: id,
  });

  useEffect(() => {
    const carregarCursosEQuestoes = async () => {
      try {
        const cursosRes = await private_api.get(`/professores/${id}/cursos`);
        setCursos(cursosRes.data || []);
      } catch (err) {
        console.error("Erro ao carregar cursos:", err);
      }
    };

    const carregarAvaliacoes = async () => {
      try {
        const res = await private_api.get(`/professores/${id}/avaliacoes`);
        setAvaliacoes(res.data || []);
      } catch (err) {
        console.error("Erro ao carregar avaliações:", err);
      } finally {
        setCarregando(false);
      }
    };

    carregarCursosEQuestoes();
    carregarAvaliacoes();
  }, [id]);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setNovaAvaliacao((prev) => ({ ...prev, [name]: value }));
  };

  const handlePerguntaChange = (index, field, value) => {
    const novasPerguntas = [...novaAvaliacao.perguntas];
    if (field === "respostaCorreta") {
      novasPerguntas[index][field] = parseInt(value);
    } else {
      novasPerguntas[index][field] = value;
    }
    setNovaAvaliacao((prev) => ({ ...prev, perguntas: novasPerguntas }));
  };

  const handleOpcaoChange = (pIndex, oIndex, value) => {
    const novasPerguntas = [...novaAvaliacao.perguntas];
    novasPerguntas[pIndex].opcoes[oIndex] = value;
    setNovaAvaliacao((prev) => ({ ...prev, perguntas: novasPerguntas }));
  };

  const adicionarPergunta = () => {
    setNovaAvaliacao((prev) => ({
      ...prev,
      perguntas: [
        ...prev.perguntas,
        {
          texto: "",
          opcoes: ["", "", "", ""],
          respostaCorreta: 0,
        },
      ],
    }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      const payload = {
        ...novaAvaliacao,
        perguntas: novaAvaliacao.perguntas,
      };

      await private_api.post("/avaliacoes", payload);
      alert("Avaliação criada com sucesso!");

      // Atualiza a lista de avaliações
      const res = await private_api.get(`/professores/${id}/avaliacoes`);
      setAvaliacoes(res.data || []);

      // Reseta o formulário
      setNovaAvaliacao({
        titulo: "",
        descricao: "",
        dataInicio: formatarDataParaInput(new Date()),
        dataFim: calcularDataFimPadrao(new Date()),
        pontuacaoMaxima: 20,
        cursoId: "",
        tipo: "escolha_multipla",
        perguntas: [
          {
            texto: "",
            opcoes: ["", "", "", ""],
            respostaCorreta: 0,
          },
        ],
        professorId: id,
      });
    } catch (error) {
      console.error("Erro ao criar avaliação:", error);
      alert("Erro ao criar avaliação.");
    }
  };

  return (
    <div className="container py-4">
      <h2 className="mb-4">Gerenciar Avaliações</h2>

      <form
        onSubmit={handleSubmit}
        className="mb-5 bg-light p-4 rounded shadow-sm"
      >
        <h4>Criar Nova Avaliação</h4>

        <div className="mb-3">
          <label className="form-label">Título</label>
          <input
            type="text"
            className="form-control"
            name="titulo"
            value={novaAvaliacao.titulo}
            onChange={handleChange}
            required
          />
        </div>

        <div className="mb-3">
          <label className="form-label">Descrição</label>
          <textarea
            className="form-control"
            name="descricao"
            value={novaAvaliacao.descricao}
            onChange={handleChange}
          />
        </div>

        <div className="row mb-3">
          <div className="col">
            <label className="form-label">Data de Início</label>
            <input
              type="datetime-local"
              className="form-control"
              name="dataInicio"
              value={novaAvaliacao.dataInicio}
              onChange={handleChange}
              required
            />
          </div>
          <div className="col">
            <label className="form-label">Data de Fim</label>
            <input
              type="datetime-local"
              className="form-control"
              name="dataFim"
              value={novaAvaliacao.dataFim}
              onChange={handleChange}
              required
            />
          </div>
        </div>

        <div className="mb-3">
          <label className="form-label">Curso</label>
          <select
            className="form-select"
            name="cursoId"
            value={novaAvaliacao.cursoId}
            onChange={handleChange}
            required
          >
            <option value="">Selecione um curso</option>
            {cursos.map((curso) => (
              <option key={curso.id} value={curso.id}>
                {curso.nome}
              </option>
            ))}
          </select>
        </div>

        <div className="mb-3">
          <label className="form-label">Pontuação Máxima</label>
          <input
            type="number"
            className="form-control"
            name="pontuacaoMaxima"
            value={novaAvaliacao.pontuacaoMaxima}
            onChange={handleChange}
          />
        </div>

        <h5 className="mt-4">Perguntas</h5>
        {novaAvaliacao.perguntas.map((pergunta, pIndex) => (
          <div key={pIndex} className="border p-3 mb-3 rounded bg-white">
            <label>Pergunta {pIndex + 1}</label>
            <input
              type="text"
              className="form-control mb-2"
              value={pergunta.texto}
              onChange={(e) =>
                handlePerguntaChange(pIndex, "texto", e.target.value)
              }
              placeholder="Texto da pergunta"
              required
            />
            {pergunta.opcoes.map((opcao, oIndex) => (
              <input
                key={oIndex}
                type="text"
                className="form-control mb-1"
                placeholder={`Opção ${oIndex + 1}`}
                value={opcao}
                onChange={(e) =>
                  handleOpcaoChange(pIndex, oIndex, e.target.value)
                }
              />
            ))}
            <label className="form-label mt-2">Resposta Correta</label>
            <select
              className="form-select"
              value={pergunta.respostaCorreta}
              onChange={(e) =>
                handlePerguntaChange(pIndex, "respostaCorreta", e.target.value)
              }
            >
              {[0, 1, 2, 3].map((opcaoIndex) => (
                <option key={opcaoIndex} value={opcaoIndex}>
                  Opção {opcaoIndex + 1}
                </option>
              ))}
            </select>
          </div>
        ))}
        <button
          type="button"
          className="btn btn-secondary mb-3"
          onClick={adicionarPergunta}
        >
          Adicionar Pergunta
        </button>
        <br />
        <button type="submit" className="btn btn-primary">
          Criar Avaliação
        </button>
      </form>

      {/* Lista de Avaliações com Submissões */}
      <h4 className="mb-3">Avaliações Criadas e Submissões</h4>
      {carregando ? (
        <p>Carregando...</p>
      ) : avaliacoes.length === 0 ? (
        <p>Nenhuma avaliação criada ainda.</p>
      ) : (
        avaliacoes.map((avaliacao) => (
          <div
            key={avaliacao.id}
            className="mb-4 bg-white p-3 rounded shadow-sm"
          >
            <h5>{avaliacao.titulo}</h5>
            <p>{avaliacao.descricao}</p>
            <p>
              Curso: <strong>{avaliacao.curso?.nome || "N/A"}</strong>
            </p>
            <p>
              Período: {new Date(avaliacao.dataInicio).toLocaleString()} até{" "}
              {new Date(avaliacao.dataFim).toLocaleString()}
            </p>
            <h6 className="mt-3">Submissões</h6>
            {avaliacao.submissoes.length === 0 ? (
              <p>Nenhuma submissão ainda.</p>
            ) : (
              <table className="table table-bordered">
                <thead>
                  <tr>
                    <th>Aluno</th>
                    <th>Pontuação</th>
                    <th>Tempo</th>
                    <th>Entregue em</th>
                  </tr>
                </thead>
                <tbody>
                  {avaliacao.submissoes.map((submissao) => (
                    <tr key={submissao.id}>
                      <td>{submissao.nomeAluno}</td>
                      <td>{submissao.pontuacao}</td>
                      <td>{submissao.tempo}</td>
                      <td>{submissao.entregue}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            )}
          </div>
        ))
      )}
    </div>
  );
};

export default LecionaAvaliacao;
